import{_ as a,c as e,o as n,ah as l}from"./chunks/framework.DE7iKuik.js";const h=JSON.parse('{"title":"使用 Satis 处理私有仓库","frontmatter":{"title":"使用 Satis 处理私有仓库","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/private-packages-with-satis.html","lastUpdated":"2026-01-20","tags":[],"link":"/docs/composer/官方文章/private-packages-with-satis","layout":"doc","sidebar":true,"aside":true,"prev":{"text":"自定义安装器","link":"/docs/composer/官方文章/installers"},"next":{"text":"HTTP 基础认证","link":"/docs/composer/官方文章/basic-authentication"}},"headers":[],"params":{"pkg":"composer/官方文章/private-packages-with-satis","sidebar":[{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]}],"versions":[]},"relativePath":"docs/composer/官方文章/private-packages-with-satis.md","filePath":"docs/[pkg].md"}'),o={name:"docs/composer/官方文章/private-packages-with-satis.md"};function i(p,s,t,c,r,u){return n(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="处理私有-packages" tabindex="-1">处理私有 packages <a class="header-anchor" href="#处理私有-packages" aria-label="Permalink to “处理私有 packages”">​</a></h1><h2 id="私有-packagist" tabindex="-1">私有 Packagist <a class="header-anchor" href="#私有-packagist" aria-label="Permalink to “私有 Packagist”">​</a></h2><p><a href="https://packagist.com/" target="_blank" rel="noreferrer">Private Packagist</a> 可以为私有的商业 packages 提供专业的托管服务，并在网页上提供对私有 packages 和公共 packages 管理，以及细粒度的权限控制。Private Packagist 会为每个 package 制作 ZIP 格式的镜像，这会让 package 安装的更快（因为压缩过了），并且由于独立于其他第三方系统，所以即便 GitHub down 了，你也可以正常进行部署，因为你的 ZIP 文件是作为镜像保存在 Private Packagist。</p><p>Private Packagist 可以作为托管 SaaS 解决方案使用，也可以作为内部部署私有 Package 的站点，并可以在网页上进行简单的设置。</p><p>Private Packagist 的一部分收入将用于支付 Composer 和 Packagist.org 的开发和托管费用，这是一种在财务上维持这些开源项目的好办法。你可以在 <a href="https://packagist.com/" target="_blank" rel="noreferrer">Packagist.com</a> 上找到关于如何设置自己的 package 的更多信息。</p><h2 id="satis" tabindex="-1">Satis <a class="header-anchor" href="#satis" aria-label="Permalink to “Satis”">​</a></h2><p>另一方面，Satis是开源的，它只是一个静态的 <code>Composer</code> 储存库生成器。它有点类似于一个超轻量的 packagist ， 可以用于托管公司的私有 packages 或者 保存自己的私有 packages 。可以从 <a href="https://github.com/composer/satis" target="_blank" rel="noreferrer">GitHub</a> 下载 或者 在命令行运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php composer.phar create-project composer/satis --stability=dev --keep-vcs</span></span></code></pre></div><h2 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to “部署”">​</a></h2><p>假设你现在有一些需要在公司中被多个人使用的 package，但是并不想开源。OK，然后你看上了 Satis 来解决这个问题。那么首先你需要一个 JSON 格式的 Satis 配置文件，并在上面写明你的软件源（<a href="https://github.com/composer/composer/blob/master/doc/05-repositories.md" target="_blank" rel="noreferrer">repositories</a>）。 下面是一份例示配置，这里在 repositories 里配置了一些 VCS 储存库，Satis 支持的 repositories 类型可以在这里找到 <a href="https://github.com/composer/composer/blob/master/doc/05-repositories.md" target="_blank" rel="noreferrer">link</a> 。如果你在这里配置 <code>&quot;require-all&quot;: true</code> ，Satis 会将你定义的 repositories 中的全部包的全部版本都加载。</p><blockquote><p>译者注： 这里支持将 <code>VCS</code> 版本控制系统, <code>Composer</code> e.g. packagist.org，<code>PEAR</code> 和 <code>Package</code>中的 package 加载到 Satis 中。</p></blockquote><p>Satis 默认会在所在文件夹中查找名字叫 <code>satis.json</code> 的文件作为配置文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;My Repository&quot;,</span></span>
<span class="line"><span>  &quot;homepage&quot;: &quot;http://packages.example.org&quot;,</span></span>
<span class="line"><span>  &quot;repositories&quot;: [</span></span>
<span class="line"><span>    { &quot;type&quot;: &quot;vcs&quot;, &quot;url&quot;: &quot;https://github.com/mycompany/privaterepo&quot; },</span></span>
<span class="line"><span>    { &quot;type&quot;: &quot;vcs&quot;, &quot;url&quot;: &quot;http://svn.example.org/private/repo&quot; },</span></span>
<span class="line"><span>    { &quot;type&quot;: &quot;vcs&quot;, &quot;url&quot;: &quot;https://github.com/mycompany/privaterepo2&quot; }</span></span>
<span class="line"><span>  ],</span></span>
<span class="line"><span>  &quot;require-all&quot;: true</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果你只想 Satis 去加载你想要的那些 package，你可以在 <code>require</code> 中指明你想要的 package，并选择你需要的版本。</p><blockquote><p>译者注： 这里的版本限定规则和 Composer.json 中一致，若有不明请参考 <a href="https://learnku.com/docs/composer/2018/versions/2098" target="_blank" rel="noreferrer">link</a></p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;repositories&quot;: [</span></span>
<span class="line"><span>    { &quot;type&quot;: &quot;vcs&quot;, &quot;url&quot;: &quot;https://github.com/mycompany/privaterepo&quot; },</span></span>
<span class="line"><span>    { &quot;type&quot;: &quot;vcs&quot;, &quot;url&quot;: &quot;http://svn.example.org/private/repo&quot; },</span></span>
<span class="line"><span>    { &quot;type&quot;: &quot;vcs&quot;, &quot;url&quot;: &quot;https://github.com/mycompany/privaterepo2&quot; }</span></span>
<span class="line"><span>  ],</span></span>
<span class="line"><span>  &quot;require&quot;: {</span></span>
<span class="line"><span>    &quot;company/package&quot;: &quot;*&quot;,</span></span>
<span class="line"><span>    &quot;company/package2&quot;: &quot;*&quot;,</span></span>
<span class="line"><span>    &quot;company/package3&quot;: &quot;2.0.0&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>接着运行命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php bin/satis build &lt;configuration file&gt; &lt;build dir&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//译者注：例示 ：</span></span>
<span class="line"><span>php bin/satis build satis.json public/</span></span></code></pre></div><p>推荐给 Satis 设置 cron 定时任务，这样 Satis 上的 package 就可以随时保持最新。</p><p>如果你的 package 在 GitHub 的私有仓库里，你应该在 build 命令中添加 <code>--no-interaction</code> (或者 <code>-n</code>) 参数，让它直接去验证 SSH 密钥，而不是要求输入密码。这对在脚本或者依赖 CI 的系统里面是一个较好的技巧。</p><blockquote><p>译者注： 如果 repositories 是来自 GitHub，那么在你的 Satis 从 GitHub 获取了一定数量的 Package 之后会被提示需要 Token，GitHub 为了防止被滥用，会有这样的限制。那么你需要在 GitHub 的个人中心里配置一个 token，设置到 Composer 上。</p></blockquote><p>接着你需要配置一个指向你的 <code>build 目录</code> 的域名，例如 <code>packages.example.org</code> 指向我们刚才的 <code>public/</code>。如果你的 PHP版本大于 5.4.0，你也可以使用内置的 CLI 服务器，作为测试时的临时方案</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php -S localhost:port -t satis-output-dir/</span></span></code></pre></div><blockquote><p>译者注： 推荐使用 Nginx</p></blockquote><h3 id="部分更新" tabindex="-1">部分更新 <a class="header-anchor" href="#部分更新" aria-label="Permalink to “部分更新”">​</a></h3><p>你可以让 Satis 只更新特定的包或者仅仅更新给定URL所指定的包。这会很大程度上减少重建 <code>package.json</code>文件所需要的时间（特别是需要加载很多 package 而且还需要为其解决依赖的情况下）。如果在代码推送到 repositories 后使用 webhooks 触发重建 <code>package.json</code> 文件的情况下，这种方式将非常有用。</p><p>使用如下命令，将仅仅查找和加载 <code>this/package</code> 和 <code>that/other-package</code> 而不会去关注别的 package 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php bin/satis build satis.json web/ this/package that/other-package</span></span></code></pre></div><p>但是请注意，这仍然会去提取和扫描所有的 VCS repositories （也就是刚刚在 satis.json 里配置的那些 repositories），因为任何 VCS repositories 都可能包含你需要的库</p><p>如果只需要扫描单个储存库并更行其中找到的所有的 package ，请将 VCS repository 的 URL 作为可选参数传递，例示如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>php bin/satis build --repository-url https://only.my/repo.git satis.json web/</span></span></code></pre></div><blockquote><p>译者注：<code>不指定 package</code>，<code>指定 package</code>，<code>指定 VCS URL 并指定 package</code> 的区别</p><ul><li><code>不指定 package</code>：将去指定的全部的 repositories 里寻找指定的全部的package，并查看是否有新的版本需要加载或者是否有版本进行了更变。</li><li><code>指定 package</code>：将去指定的全部的 repositories 里，查看指定的 package 是否有新的版本需要加载或者是否有版本进行了更变。</li><li><code>指定 VCS URL 并指定 package</code> ： 仅仅去指定的 VCS URL 里，查看指定的 package 是否有新的版本需要加载或者是否有版本进行了更变</li></ul></blockquote><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><hr><p>你需要在项目的 <code>composer.json</code> 里添加如下字段来使用 <code>packages.example.org</code> 作为 这个项目的 Composer 源，这个修改的影响将仅限于这个项目，而不会影响到别的项目。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;repositories&quot;: [ { &quot;type&quot;: &quot;composer&quot;, &quot;url&quot;: &quot;http://packages.example.org/&quot; } ],</span></span>
<span class="line"><span>  &quot;require&quot;: {</span></span>
<span class="line"><span>    &quot;company/package&quot;: &quot;1.2.0&quot;,</span></span>
<span class="line"><span>    &quot;company/package2&quot;: &quot;1.5.2&quot;,</span></span>
<span class="line"><span>    &quot;company/package3&quot;: &quot;dev-master&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h3><p>为了保护你的私有库，你可以要求客户端使用客户端证书通过 SSH/SSL 连接 Satis。 你可以在 <code>satis.json</code> 中的 repositories 中配置它。</p><p>通过 SSH 使用自定义 存储库的示例（需要SSH2 PECL 拓展）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;repositories&quot;: [{</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;composer&quot;,</span></span>
<span class="line"><span>    &quot;url&quot;: &quot;ssh2.sftp://example.org&quot;,</span></span>
<span class="line"><span>    &quot;options&quot;: {</span></span>
<span class="line"><span>      &quot;ssh2&quot;: {</span></span>
<span class="line"><span>        &quot;username&quot;: &quot;composer&quot;,</span></span>
<span class="line"><span>        &quot;pubkey_file&quot;: &quot;/home/composer/.ssh/id_rsa.pub&quot;,</span></span>
<span class="line"><span>        &quot;privkey_file&quot;: &quot;/home/composer/.ssh/id_rsa&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }]</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>Tip: 查阅 <a href="https://secure.php.net/manual/en/wrappers.ssh2.php#refsect1-wrappers.ssh2-options" target="_blank" rel="noreferrer">SSH2 配置参数</a> 了解更多信息。</p></blockquote><p>使用客户端证书通过 SSL/TLS（HTTPS）的方式连接的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;repositories&quot;: [{</span></span>
<span class="line"><span>     &quot;type&quot;: &quot;composer&quot;,</span></span>
<span class="line"><span>     &quot;url&quot;: &quot;https://example.org&quot;,</span></span>
<span class="line"><span>     &quot;options&quot;: {</span></span>
<span class="line"><span>       &quot;ssl&quot;: {</span></span>
<span class="line"><span>         &quot;local_cert&quot;: &quot;/home/composer/.ssl/composer.pem&quot;</span></span>
<span class="line"><span>       }</span></span>
<span class="line"><span>     }</span></span>
<span class="line"><span>  }]</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>Tip: 查阅 <a href="https://secure.php.net/manual/en/context.ssl.php" target="_blank" rel="noreferrer">ssl 配置参数</a> 了解更多信息。</p></blockquote><p>使用 自定义的HTTP header 字段进行身份验证的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;repositories&quot;: [{</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;composer&quot;,</span></span>
<span class="line"><span>    &quot;url&quot;: &quot;https://example.org&quot;,</span></span>
<span class="line"><span>    &quot;options&quot;:  {</span></span>
<span class="line"><span>      &quot;http&quot;: {</span></span>
<span class="line"><span>        &quot;header&quot;: [</span></span>
<span class="line"><span>          &quot;API-TOKEN: YOUR-API-TOKEN&quot;</span></span>
<span class="line"><span>        ]</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }]</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="认证" tabindex="-1">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to “认证”">​</a></h3><p>当您的私有存储库受到密码保护时，您可以永久存储身份验证详细信息。 Composer 第一次需要对某个域进行身份验证时，它会提示您输入用户名/密码，然后会询问您是否要存储它。</p><p>存储可以在 <code>COMPOSER_HOME/auth.json</code> 文件中全局完成（<code>COMPOSER_HOME</code> 在 Windows 上默认为  <code>~/.composer</code> 或 <code>%APPDATA%/Composer</code> ）也可以直接在 composer.json 旁边的项目目录中完成。</p><p>如果需要将生产计算机配置为能够运行非交互式安装，还可以使用 config 命令手动配置这些。例如，要输入 example.org 的凭据，可以键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>composer config http-basic.example.org username password</span></span></code></pre></div><p>这会将它存储在当前目录的 auth.json 中，但是如果您想让它全局可用，您可以使用 <code>--global</code> (<code>-g</code>) 标志。</p><h3 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to “下载”">​</a></h3><p>当 GitHub ，GitLab 或 BitBucket 存储库镜像到您本地时，构建过程将包括这些平台提供的下载位置。这意味着存储库和您的设置取决于这些服务的可用性。</p><p>同时，这意味着托管在其它地方（在另一个服务上或在 Subversion 中）的所有代码都将没有可用的下载，因此安装通常需要更长的时间。</p><p>为了使您的安装能够为您的所有包（Git，Mercurial 和 Subversion）创建下载，请将以下内容添加到您的 <code>satis.json</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;archive&quot;: {</span></span>
<span class="line"><span>    &quot;directory&quot;: &quot;dist&quot;,</span></span>
<span class="line"><span>    &quot;format&quot;: &quot;tar&quot;,</span></span>
<span class="line"><span>    &quot;prefix-url&quot;: &quot;https://amazing.cdn.example.org&quot;,</span></span>
<span class="line"><span>    &quot;skip-dev&quot;: true</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="选项解释" tabindex="-1">选项解释 <a class="header-anchor" href="#选项解释" aria-label="Permalink to “选项解释”">​</a></h4><ul><li><p><code>directory</code> ：必须，dist 的位置 （在 <code>output-dir</code> 里面）</p></li><li><p><code>format</code> ：可选 <code>zip</code> （默认）或 <code>tar</code></p></li><li><p><code>prefix-url</code> ：可选，下载位置，主页（来自 <code>satis.json</code>）默认为 <code>directory</code></p></li><li><p><code>skip-dev</code>：可选，默认情况下为 <code>false</code> ，启用时（<code>true</code>）表示不会为分支创建下载</p></li><li><p><code>absolute-directory</code> ：可选，一个本地目录，其中 dist 文件被转储而不是输出 <code>output-dir</code>/<code>directory</code></p></li><li><p><code>whitelist</code> ：可选，如果设置为包名称列表，则只会转储这些包的 dist 文件</p></li><li><p><code>blacklist</code> ：可选，如果设置为包名称列表，则不会转储这些包的 dist 文件</p></li><li><p><code>checksum</code> ：可选，默认情况下为 <code>true</code> ，禁用时（<code>false</code>）不会为 dist 文件提供 sha1 校验</p><p>启用后，所有下载（包括来自 GitHub 和 BitBucket 的下载） 将替换为本地版本。</p></li></ul><h4 id="prefix-url" tabindex="-1">prefix-url <a class="header-anchor" href="#prefix-url" aria-label="Permalink to “prefix-url”">​</a></h4><p>如果下载最终位置位于私有 Amazon S3 存储桶或 CDN 主机上，则使用其他主机对 URL 进行预处理特别有用。CDN 将大大缩短下载时间，从而改善软件包安装。</p><p>例如：为 <code>https://my-bucket.s3.amazonaws.com</code> （和 <code>directory</code> 设置为 <code>dist</code>）的 <code>prefix-url</code> 创建下载 URL ，如下所示： <code>https://my-bucket.s3.amazonaws.com/dist/vendor-package-version-ref.zip</code> 。</p><h3 id="网络输出" tabindex="-1">网络输出 <a class="header-anchor" href="#网络输出" aria-label="Permalink to “网络输出”">​</a></h3><ul><li><code>output-html</code> ：optional ，默认情况下为 <code>true</code> ，当禁用（<code>false</code>）时不会生成 <code>output-dir</code>/index.html 页面。</li><li><code>twig-template</code>：可选，是 <code>output-dir</code>/index.html 页面的个性化 <a href="https://twig.sensiolabs.org/" target="_blank" rel="noreferrer">Twig</a> 模板的路径。</li></ul><h3 id="被遗弃的包" tabindex="-1">被遗弃的包 <a class="header-anchor" href="#被遗弃的包" aria-label="Permalink to “被遗弃的包”">​</a></h3><p>为了使您的安装能指示某些包已被遗弃，请将以下内容添加到您的 <code>satis.json</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;abandoned&quot;: {</span></span>
<span class="line"><span>    &quot;company/package&quot;: true,</span></span>
<span class="line"><span>    &quot;company/package2&quot;: &quot;company/newpackage&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>true</code> 值表示包被真正放弃，而 <code>&quot;company/newpackage&quot;</code> 指定包被 <code>company/newpackage</code> 包替换。</p><p>请注意，在自己的 <code>composer.json</code> 文件中设置的所有包也将被标记为已放弃。</p><h3 id="解决依赖关系" tabindex="-1">解决依赖关系 <a class="header-anchor" href="#解决依赖关系" aria-label="Permalink to “解决依赖关系”">​</a></h3><p>可以自动解决并添加项目的所有依赖项。这可以与“下载”功能一起使用，以获得完整的本地镜像包。将以下内容添加到您的 <code>satis.json</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;require-dependencies&quot;: true,</span></span>
<span class="line"><span>  &quot;require-dev-dependencies&quot;: true</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在搜索包时，satis 将尝试从列出的存储库中解析所有必须的包。因此，如果您需要 Packagist 的软件包，则需要在 <code>satis.json</code> 中定义它。</p><p>仅当 <code>require-dev-dependencies</code> 参数设置为 true 时才打包 Dev 依赖项。</p><h3 id="其他选择" tabindex="-1">其他选择 <a class="header-anchor" href="#其他选择" aria-label="Permalink to “其他选择”">​</a></h3><ul><li><code>providers</code>：可选，默认情况下为 <code>false</code> 启用时（<code>true</code>）每个包都将被转储到一个单独的包含文件中，只有在真正需要包时才由 composer 加载。加快编译器处理存储库，如 f.i 包装的巨大数量的包。</li><li><code>output-dir</code> ：可选，定义在调用 <code>build</code> 命令时，如果没有提供参数作为参数，则输出库文件的位置。</li><li><code>config</code> ：可选，允许您定义来自 composer 的所有配置选项，除了 <code>archive-format</code> 和 <code>archive-dir</code> ，因为配置项是通过 <a href="https://github.com/composer/composer/blob/master/doc/articles/handling-private-packages-with-satis.md#downloads" target="_blank" rel="noreferrer">archive</a> 完成的。有关详细信息，请参阅 <a href="https://getcomposer.org/doc/04-schema.md#config" target="_blank" rel="noreferrer">config schema</a> 上的文档。</li><li><code>notify-batch</code> ：可选，指定一个用户每次安装包时调用的 URL 。参阅 <a href="https://getcomposer.org/doc/05-repositories.md#notify-batch" target="_blank" rel="noreferrer">notify-batch</a>。</li></ul>`,76)])])}const k=a(o,[["render",i]]);export{h as __pageData,k as default};
